// Authored content for 3.2.11.1 Gene mutations (OxfordAQA 9610 v5.1, printed p.26; statements 3.2.11.1.s1–s4 in
// data/spec.js). Official wording: "Gene mutations involve a change in the base sequence of DNA. They arise
// spontaneously during DNA replication. Mutagens are physical or chemical agents that increase the frequency of
// mutations. Base deletion and base substitution as examples of gene mutation. Because of the degenerate nature of the
// genetic code, not all mutations result in a change in the sequence of the encoded amino acids. Students should be able
// to predict the outcome of specific mutations on amino acid sequences when provided with suitable information relating
// to the genetic code." (The printed PDF says "degenerative"; data/spec.js and this page use "degenerate", the
// standard term.) Insertion, duplication and inversion are supporting; silent, missense, nonsense and frameshift are
// supporting terms; in-frame deletion of three bases is extension. Every sequence is translated with B.proteinModel
// (the platform genetic code from 3.1.8, not retyped), with the strand convention of 3.1.8.2: coding strand and mRNA
// 5′→3′, template strand 3′→5′ underneath. Real data: the beta-globin (HBB) sequence and the HbS change, sources in
// data/content/_mutation-art.js and on the page.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.mutationArt, M = window.BIO.mutationModel, P = window.BIO.proteinModel, PA = window.BIO.proteinArt;
  const R = "3.2.11.1";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const MONO = PA.MONO, mono = (x) => `<span style="font-family:${MONO}">${x}</span>`;
  const CL = (list) => PA.codonList(list);
  const sp = (s) => s.match(/.{1,3}/g).join(" ");
  const tr = (m) => P.codons(m).map((c) => (P.aa(c) === "STOP" ? "stop" : P.aa(c))).join("–");
  const check = (c, m) => { if (!c) console.warn("3.2.11.1 check failed: " + m); };

  // ---- Worked example (computed): template strand 3′→5′ ----
  const WT = "TACCGTAAAACCGTCATT"; const WM = P.templateToMrna(WT);
  const mutT = (i, b) => WT.slice(0, i) + b + WT.slice(i + 1), delT = (i) => WT.slice(0, i) + WT.slice(i + 1);
  const W1 = P.templateToMrna(mutT(8, "G")), W2 = P.templateToMrna(mutT(6, "T")), W3 = P.templateToMrna(mutT(11, "T")), W4 = P.templateToMrna(delT(4));
  check(tr(WM) === "Met–Ala–Phe–Trp–Gln–stop" && tr(W1) === tr(WM) && tr(W2) === "Met–Ala–Ile–Trp–Gln–stop" && P.translate(W3).join("-") === "Met-Ala-Phe" && tr(W4) === "Met–Asp–Phe–Gly–Ser", "worked example");
  const WCODONS = ["AUG", "GCA", "UUU", "UUC", "AUU", "UGG", "UGA", "CAG", "UAA", "GAU", "GGC", "AGU"];

  // ---- Data question (computed) ----
  const DT = "TACAAGCCAGTAACT"; const DM = P.templateToMrna(DT); const DS = P.templateToMrna(DT.slice(0, 8) + "G" + DT.slice(9)); const DD = P.templateToMrna(DT.slice(0, 3) + DT.slice(4));
  check(P.translate(DM).join("-") === "Met-Phe-Gly-His" && P.translate(DS).join("-") === "Met-Phe-Gly-His" && P.codons(DD).map(P.aa).join("-") === "Met-Ser-Val-Ile", "data question");
  const DCODONS = ["AUG", "UUC", "GGU", "GGC", "CAU", "UGA", "UCG", "GUC", "AUU"];

  // ---- Gene 1 and HBB checks used by the interactive questions ----
  const G1 = M.GENES[0].coding, HBB = M.GENES[2].coding;
  const iv1 = M.classify(G1, { type: "sub", pos: 13, base: "C" }), iv2 = M.classify(G1, { type: "del", pos: 8 }), iv3 = M.classify(HBB, { type: "sub", pos: 19, base: "T" });
  check(iv1.kind === "unchanged" && iv2.kind === "frameshift" && iv2.firstDiff === 2 && iv3.kind === "missense" && iv3.mutated.aas[6] === "Val" && iv3.original.aas[6] === "Glu", "interactive keys");

  const SOURCES = `<p class="tiny muted"><strong>Sources</strong> (checked 14 November 2026): human beta-globin coding sequence, <a href="${M.SRC.hbb.url}" target="_blank" rel="noopener">HBB NM_000518.4 coding DNA reference sequence</a> (Leiden Open Variation Database: c.1–c.30 ATG GTG CAT CTG ACT CCT GAG GAG AAG TCT, Met Val His Leu Thr Pro Glu Glu Lys Ser); sickle-cell haemoglobin variant HBB:c.20A&gt;T, codon 6 GAG&gt;GTG, Glu&gt;Val (<a href="https://ithanet.eu/db/ithagenes?ithaID=824" target="_blank" rel="noopener">IthaGenes, ithaID 824</a>). The genetic code is the standard code used throughout the platform (3.1.8). All other sequences on this page are hypothetical, written for teaching.</p>`;

  // ---- Mutation Explorer (kind mutationExplorer) ----
  const explorer = { kind: "mutationExplorer", title: "Mutation Explorer",
    note: "Choose a gene, choose a base pair and make a substitution or a deletion. Predict the effect, then check: the mutated gene is transcribed and translated and the two polypeptides are compared. The number above each base pair is its position; the coding strand (5′→3′) is on top and the template strand (3′→5′) below. The genetic code table is provided, as in the exam.",
    questions: [
      { id: `q-${R}-iv1`, ref: R, stmts: S(3, 4), type: "mcq", marks: 1, stem: "In Gene 1, change the last base of the GGA codon (base 14 of the coding strand) from A to C. What happens to the polypeptide?", options: ["No change: GGC also codes for glycine", "Glycine is replaced by another amino acid", "The polypeptide stops at that codon", "Every amino acid after that codon changes"], answer: 0, explanation: "GGA and GGC both code for Gly: the code is degenerate, so this substitution does not change the amino acid sequence (a silent mutation, supporting term)." },
      { id: `q-${R}-iv2`, ref: R, stmts: S(2, 4), type: "mcq", marks: 1, stem: "In Gene 1, delete the first base of codon 3 (the T of TTC, base 9 of the coding strand). Which describes the result?", options: ["The first two amino acids are unchanged; from the third onwards the amino acids are different", "Only the third amino acid changes", "The polypeptide is unchanged because the code is degenerate", "The polypeptide is one amino acid shorter but otherwise unchanged"], answer: 0, explanation: `Met–Ala are unchanged, then every codon is read in a new frame: ${iv2.mutated.aas.slice(2).join("–")}… A one-base deletion shifts the reading frame (frameshift).` },
      { id: `q-${R}-iv3`, ref: R, stmts: S(2, 4), type: "mcq", marks: 1, stem: "Choose the real beta-globin (HBB) sequence and change base 20 of the coding strand from A to T. What is the effect?", options: ["Codon 7 (GAG) becomes GUG: glutamate is replaced by valine", "Codon 7 becomes a stop codon", "The reading frame shifts after base 20", "No change: GUG also codes for glutamate"], answer: 0, explanation: "GAG (Glu) becomes GUG (Val): one base substitution changes one amino acid. This is the change in sickle-cell haemoglobin (by the protein convention it is called position 6, because the first methionine is removed)." },
      { id: `q-${R}-iv4`, ref: R, stmts: S(3), type: "short", marks: 2, stem: "In Gene 2, try substitutions in the third base of the CTG (Leu) codon and of the TGG (Trp) codon. Explain why the results differ. (2 marks)", scheme: [{ point: "Leucine has several codons (six) / CUU, CUC, CUA all code for Leu, so any change to the third base still codes for leucine (no change)", marks: 1 }, { point: "Tryptophan has only one codon (UGG), so any change alters the amino acid (or gives a stop codon: UGA, UAG)", marks: 1 }], model: "The code is degenerate, but not equally for every amino acid. Leucine has six codons and CUU, CUC, CUA and CUG all code for leucine, so a substitution in the third base of CUG leaves the amino acid unchanged. Tryptophan has only one codon, UGG, so any substitution changes it: changing its third base gives UGU or UGC (cysteine) or UGA (a stop codon).", commonErrors: "Saying the third base 'does not matter' for every codon." },
    ] };

  window.BIO.content[R] = {
    status: "draft",
    banner: "dna-model", bannerText: "A change in one base pair can change a codon, an amino acid and a protein, or, because the code is degenerate, change nothing at all.",
    keywords: ["gene mutation", "mutation", "base sequence", "base substitution", "substitution", "base deletion", "deletion", "insertion", "mutagen", "mutagens", "ultraviolet", "UV", "ionising radiation", "X-rays", "carcinogen", "spontaneous", "DNA replication", "proofreading", "degenerate", "genetic code", "codon", "reading frame", "frameshift", "silent mutation", "missense", "nonsense", "stop codon", "sickle cell", "beta-globin", "HBB", "template strand", "coding strand"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.2.11.1).</strong> Gene mutations are <strong>changes in the base sequence of DNA</strong>; they arise <strong>spontaneously during DNA replication</strong>; <strong>mutagens</strong> (physical or chemical) <strong>increase the frequency</strong> of mutations; <strong>base deletion</strong> and <strong>base substitution</strong> as examples; because the genetic code is <strong>degenerate</strong>, not every mutation changes the amino acid sequence; and you must <strong>predict the effect of a given mutation on the amino acid sequence</strong> when you are given the relevant part of the genetic code. You never need to recall the code. <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">stretch</span></div>

<h2 data-stmt="${R}.s1">1. What a gene mutation is <span class="badge teal">required</span></h2>
<p>A gene is a sequence of bases in DNA that codes for the amino acid sequence of a polypeptide (<a href="#/topic/3.1.8.1">3.1.8.1</a>). A <strong>gene mutation</strong> is a <strong>change in the base sequence of DNA</strong>. Because the mRNA is transcribed from the DNA (<a href="#/topic/3.1.8.2">3.1.8.2</a>), a change in the DNA can change the mRNA codons and therefore, sometimes, the amino acids that are joined together during translation.</p>
<p>A gene mutation changes a <strong>base pair</strong>: if one base of a pair changes, the next round of replication gives a matching (complementary) change on the other strand, so both strands of the DNA in that cell's descendants carry the new sequence.</p>
<p class="small"><span class="badge">supporting</span> Mutations that change the structure or number of whole chromosomes are a different kind of mutation and are not part of this subsection. A mutation in a body cell is passed only to the cells formed from it by mitosis; only a mutation in a cell that forms gametes can be passed to offspring.</p>

<h2 data-stmt="${R}.s1">2. Mutations arise spontaneously during DNA replication <span class="badge teal">required</span></h2>
<p>DNA is copied by semi-conservative replication before every cell division (<a href="#/topic/3.1.7.3">3.1.7.3</a>). Free nucleotides pair with the exposed bases on each template strand and DNA polymerase joins them. Very occasionally a <strong>wrong nucleotide is built in</strong> (for example a T opposite a G), or a nucleotide is missed out or added. Such errors happen by chance, without any outside cause: mutations <strong>arise spontaneously</strong>. When the DNA is next replicated, the strand carrying the wrong base acts as a template, so the error becomes a <strong>permanent change in the base pair</strong> in that cell's descendants.</p>
<p><span class="badge">supporting</span> DNA polymerase checks each base as it is added and removes most wrong ones (proofreading), and other enzymes repair many mistakes and much damage afterwards. This is why spontaneous mutations are rare. Errors that escape correction remain.</p>
<p>The figure follows one mistake through two rounds of replication.</p>

<h2 data-stmt="${R}.s1">3. Mutagens increase the frequency of mutation <span class="badge teal">required</span></h2>
<p>A <strong>mutagen</strong> is a <strong>physical or chemical agent that increases the frequency (rate) of mutations</strong>. Mutagens do not create a new kind of process: mutations happen anyway, and a mutagen makes them happen <strong>more often</strong>.</p>
<table class="tbl"><thead><tr><th>Type</th><th>Examples</th><th>How it can change DNA <span class="badge">supporting</span></th></tr></thead><tbody>
<tr><td><strong>Physical</strong></td><td><strong>Ionising radiation</strong>: X-rays, gamma rays, and the alpha and beta particles given out by radioactive substances</td><td>Damages bases and can break one or both strands of the DNA; errors are made when the damage is repaired or copied.</td></tr>
<tr><td><strong>Physical</strong></td><td><strong>Ultraviolet (UV) light</strong>, for example in sunlight and from sunbeds</td><td>Can join two neighbouring bases on the same strand (for example two thymines), so the strand is copied wrongly.</td></tr>
<tr><td><strong>Chemical</strong></td><td>Some substances in <strong>tobacco smoke</strong>; some industrial chemicals</td><td>Can bind to bases or change their structure, so the wrong base pairs with them during replication.</td></tr></tbody></table>
<p>Mutagens act <strong>at random</strong>: they increase the chance of a change anywhere in the DNA but do not choose which gene or which base changes. A mutagen that increases the risk of cancer is called a <strong>carcinogen</strong> (see <a href="#/topic/3.2.11.2">3.2.11.2</a>). <span class="badge">supporting</span> Some viruses can also cause mutations; they are not named in this specification.</p>

<h2 data-stmt="${R}.s2">4. Base substitution and base deletion <span class="badge teal">required</span></h2>
<ul><li><strong>Base substitution</strong>: one base (one base pair) is <strong>replaced by a different base</strong>. The number of bases is unchanged, so only <strong>one codon</strong> changes (the code is non-overlapping, 3.1.8.1). That codon may code for the same amino acid, a different amino acid, or a stop codon.</li>
<li><strong>Base deletion</strong>: one base (one base pair) is <strong>removed</strong>. Every base after it moves back by one, so the <strong>reading frame shifts</strong>: every codon from the deletion onwards is different. Many amino acids change, and a stop codon often appears early in the new frame.</li></ul>
<p>The figure compares a substitution and a deletion in the same short gene. Work codon by codon from the start codon, using the template strand, the mRNA or the coding strand, whichever you are given.</p>
<p class="small"><span class="badge">supporting</span> Other gene mutations: <strong>insertion</strong> (an extra base is added: also a frameshift), <strong>duplication</strong> (a section of bases is repeated) and <strong>inversion</strong> (a section of bases is reversed). Only substitution and deletion are named in the specification.</p>

<h2 data-stmt="${R}.s3">5. The degenerate code: not every mutation changes the amino acids <span class="badge teal">required</span></h2>
<p>There are 64 possible codons but only 20 amino acids, and most amino acids are coded for by <strong>more than one codon</strong>: the genetic code is <strong>degenerate</strong> (<a href="#/topic/3.1.8.1">3.1.8.1</a>). Codons for the same amino acid often differ only in their third base. So a base substitution can change a codon into <strong>another codon for the same amino acid</strong>: the amino acid sequence, and so the polypeptide, is unchanged.</p>
<p>The same codon can be changed in different ways with different results:</p>
<ul><li>the new codon codes for the <strong>same amino acid</strong>: no change to the amino acid sequence (<span class="badge">supporting</span> a <em>silent</em> mutation);</li>
<li>the new codon codes for a <strong>different amino acid</strong>: one amino acid changes (<span class="badge">supporting</span> a <em>missense</em> mutation);</li>
<li>the new codon is a <strong>stop codon</strong>: translation ends early and the polypeptide is shorter (<span class="badge">supporting</span> a <em>nonsense</em> mutation).</li></ul>
<p>Degeneracy protects only against some substitutions. Amino acids with a single codon (methionine, AUG; tryptophan, UGG) are changed by any substitution, and a change to the first or second base usually changes the amino acid.</p>

<h2 data-stmt="${R}.s2 ${R}.s4">6. Deletions shift the reading frame <span class="badge teal">required</span></h2>
<p>Codons are read in sequence, three bases at a time, from a fixed starting point (the start codon). Deleting one base changes the grouping of <strong>every</strong> base after it: the <strong>reading frame</strong> shifts (<span class="badge">supporting</span> a <em>frameshift</em>). The amino acids before the deletion are unchanged; after it, almost all are different, and a stop codon usually appears early in the new frame. Degeneracy cannot protect against this, so a deletion near the start of a gene usually has a much bigger effect than a single substitution.</p>
<ul class="small"><li>A deletion near the <strong>end</strong> of a gene changes fewer amino acids than one near the start.</li>
<li><span class="badge amber">stretch</span> Deleting <strong>three</strong> neighbouring bases removes one codon's worth of bases, so the frame is restored after the deletion: the polypeptide loses one amino acid (and one may change if the three bases straddle two codons).</li></ul>
<p>Use the explorer to make your own substitutions and deletions, predict the effect, and then check it codon by codon in the table it gives.</p>

<h2 data-stmt="${R}.s3 ${R}.s4">7. Why mutations have different effects <span class="badge teal">required</span></h2>
<p>A protein's function depends on its tertiary structure, which depends on its amino acid sequence (<a href="#/topic/3.1.1.4">3.1.1.4</a>, <a href="#/topic/3.1.8.3">3.1.8.3</a>). A change in one amino acid changes one R group, which may alter the hydrogen bonds, ionic bonds and disulfide bridges that hold the folded shape. If this changes the <strong>active site</strong> of an enzyme (<a href="#/topic/3.1.3.1">3.1.3.1</a>) or a binding site, the protein may not work. But the effect can stop at any stage, as the flow chart shows.</p>
<p>So mutations range from <strong>no effect</strong>, through <strong>small effects</strong>, to a protein that does not work at all. Most mutations are neutral or harmful; a few can be beneficial and are a source of new alleles (<a href="#/topic/3.1.6">3.1.6</a>). A mutation does not have to cause disease, and only some mutations, in particular genes, contribute to cancer (<a href="#/topic/3.2.11.2">3.2.11.2</a>).</p>
<div class="notice small"><strong>A real example: sickle-cell haemoglobin.</strong> In the gene for the beta-globin polypeptide of haemoglobin (HBB), a single base substitution changes the codon GAG (glutamate) to GTG (valine) in the coding strand. One amino acid in a chain of 146 is changed, but this one change, from a charged R group to a non-polar one, alters how haemoglobin molecules behave when they unload oxygen, and red blood cells can become distorted (sickle-shaped). <span class="badge">supporting</span> By protein convention this is called position 6, because the first methionine is removed from the finished polypeptide; counting codons from ATG it is codon 7.</div>

<h2 data-stmt="${R}.s4">8. Predicting the effect of a mutation from provided information <span class="badge teal">required</span></h2>
<p>Exam questions give you a DNA or mRNA sequence and the codons you need. Work methodically:</p>
<ol><li><strong>Check which sequence you have.</strong> Template strand (3′→5′): pair each base to get the mRNA (A→U, T→A, G→C, C→G). Coding strand (5′→3′): copy it, changing T to U. mRNA: use it directly.</li>
<li><strong>Find the reading frame.</strong> Start at the start codon (AUG) and split the mRNA into non-overlapping triplets.</li>
<li><strong>Translate the original</strong> codon by codon with the table you are given, stopping at a stop codon.</li>
<li><strong>Make the change</strong> in the same strand, convert again and <strong>re-split from the start codon</strong>. For a deletion, the codons after it regroup.</li>
<li><strong>Compare</strong> the two amino acid sequences and describe the difference: none; one amino acid changed (name both); stops early (how many amino acids are left); or all changed from a point onwards.</li></ol>
<p><strong>Worked example.</strong> A DNA template strand (3′→5′) reads ${mono(sp(WT))}. The mRNA is ${mono(sp(WM))}.</p>
${CL(WCODONS)}
<ul class="small"><li>Original: <strong>${tr(WM)}</strong>.</li>
<li>Template base 9 changes from A to G (AAA → AAG): codon 3 becomes ${mono(P.codons(W1)[2])}, still Phe. <strong>No change</strong>: the code is degenerate.</li>
<li>Template base 7 changes from A to T (AAA → TAA): codon 3 becomes ${mono(P.codons(W2)[2])}: <strong>Phe is replaced by Ile</strong>; the rest is unchanged.</li>
<li>Template base 12 changes from C to T (ACC → ACT): codon 4 becomes ${mono(P.codons(W3)[3])}, a stop codon: the polypeptide is <strong>${P.translate(W3).join("–")}</strong>, only three amino acids.</li>
<li>Template base 5 (G) is deleted: the mRNA becomes ${mono(sp(W4))}: <strong>${tr(W4)}…</strong>, every codon after the deletion is regrouped (the frame has shifted), so most of the amino acids after it change. Here the third is still Phe, by chance: UUU still codes for Phe.</li></ul>

<h2 data-stmt="${R}.s1 ${R}.s2 ${R}.s3 ${R}.s4">9. Common misconceptions <span class="badge teal">required</span></h2>
<ul><li><strong>"Every mutation changes the protein."</strong> Because the code is degenerate, many substitutions give a codon for the same amino acid, and changes outside the coding sequence may not affect the polypeptide.</li>
<li><strong>"Every substitution is harmless because the code is degenerate."</strong> Only some substitutions are silent; others change an amino acid or create a stop codon.</li>
<li><strong>"Mutations are caused by mutagens."</strong> Mutations arise spontaneously during replication; mutagens <em>increase the frequency</em>.</li>
<li><strong>"A mutagen causes a particular mutation."</strong> Mutagens act at random; they raise the chance of changes anywhere in the DNA.</li>
<li><strong>"A deletion removes one amino acid."</strong> Deleting one base shifts the reading frame, so every codon after it changes. (Deleting three bases removes one amino acid: stretch.)</li>
<li><strong>"All mutations cause cancer" or "all mutations are harmful."</strong> Most mutations have little or no effect; cancer needs particular changes, usually several, in genes that control cell division.</li>
<li><strong>"The mRNA has the same sequence as the template strand."</strong> It is complementary to the template strand and has the coding strand's sequence with U for T.</li>
<li><strong>"The mutation changes the amino acid, which then changes the DNA."</strong> The direction is DNA → mRNA → amino acid sequence, never the reverse.</li></ul>
${SOURCES}`,
    diagrams: [
      { id: "d-3.2.11.1-1", title: "A spontaneous mutation during DNA replication", status: "draft", svg: A.replicationError(), caption: "During replication a T is wrongly paired with a G. If the mismatch is not corrected, the next replication of that strand pairs an A with the T, so an A–T pair has permanently replaced the original G–C pair: a base substitution. Mutagens make such changes happen more often (see the table below). Schematic; only five base pairs shown.", alt: "Three steps: a parent DNA molecule with a G–C pair; replication producing one molecule with a G–T mismatch and one correct copy; the next replication producing one molecule with G–C and one with A–T in that position." },
      { id: "d-3.2.11.1-2", title: "Base substitution and base deletion", status: "draft", svg: A.subDel(), caption: "The same short gene as DNA template strand (3′→5′), mRNA (5′→3′) and amino acids. A substitution changes one codon (CAU → GAU) and one amino acid (His → Asp). A deletion of one base pair shifts the reading frame, so every codon after it changes (Ser, Asp, Ile, Gly…). Hypothetical sequence; codons from the standard genetic code.", alt: "Three rows of a gene with codons bracketed and amino acids below: original Met Ala Phe Gly His Trp stop; after substitution Met Ala Phe Gly Asp Trp stop; after deletion Met Ala Ser Asp Ile Gly." },
      { id: "d-3.2.11.1-3", title: "The degenerate code: one codon, three substitutions", status: "draft", svg: A.degenerate(), caption: "UAC codes for tyrosine. A change of its third base to U gives UAU, still tyrosine (no change); a change of its first base to C gives CAC, histidine; a change of its third base to A gives UAA, a stop codon. Glycine has four codons that differ only in the third base. The terms silent, missense and nonsense are supporting.", alt: "The codon UAC with arrows to UAU (tyrosine, same amino acid), CAC (histidine, different amino acid) and UAA (stop). Below, the four glycine codons GGU, GGC, GGA and GGG." },
      { id: "d-3.2.11.1-4", title: "Why mutations have different effects", status: "draft", svg: A.effects(), caption: "A changed base can change a codon, then the amino acid sequence, the bonds between R groups, the folding and the function of the protein. The effect can stop at different points: a silent change at the codon; little effect if the new amino acid is similar or far from the active site; a large effect if the active site or a binding site changes.", alt: "A vertical flow chart of six steps from a changed DNA base to a changed protein function, with side notes on where the effect can stop, and a list of the factors that decide the effect." },
    ],
    interactives: [explorer],
    focus: [
      { slot: "rbc-sem", title: "One base, one amino acid: sickle-cell haemoglobin", ref: R, explanation: () => `<p>These are <strong>normal</strong> red blood cells, with their biconcave disc shape. Each is packed with haemoglobin, whose beta-globin chains are coded for by the HBB gene. In the sickle-cell allele, a single <strong>base substitution</strong> in the coding strand changes codon GAG (glutamate) to GTG (valine). That one change in 146 amino acids makes the haemoglobin molecules stick together into long fibres when they are not carrying oxygen, so red blood cells can become stiff and sickle-shaped and block small blood vessels.</p><p class="small">The example shows that one substitution changes only one amino acid (the code is non-overlapping), yet that one amino acid can matter a great deal if it changes how the protein behaves. Sources: HBB reference sequence (LOVD) and IthaGenes, checked 14 November 2026.</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(2, 4), type: "short", marks: 3, stem: `The first seven codons of the coding strand of the normal HBB gene are ATG GTG CAT CTG ACT CCT GAG. In the sickle-cell allele the 20th base, A, is replaced by T.\n${CL(["AUG", "GUG", "CAU", "CUG", "ACU", "CCU", "GAG", "GUG"])}(a) Name the type of mutation. (1 mark) (b) Use the information to describe the effect on the amino acid sequence. (2 marks)`, scheme: [{ point: "(a) Base substitution", marks: 1 }, { point: "(b) The 7th codon changes from GAG to GUG (in mRNA) / GAG to GTG in the coding strand", marks: 1 }, { point: "(b) Glutamate (Glu) is replaced by valine (Val); all other amino acids unchanged", marks: 1 }], model: "(a) A base substitution. (b) Base 20 is the second base of the seventh codon, so the mRNA codon changes from GAG to GUG. GAG codes for glutamate and GUG for valine, so one glutamate is replaced by valine; because the code is non-overlapping, all the other amino acids are unchanged.", commonErrors: "Calling it a deletion; saying the reading frame shifts; saying several amino acids change." } },
      { slot: "gel-sequencing", title: "Finding a mutation by reading the bases", ref: R, explanation: () => `<p>This is a diagram of a sequencing gel: each lane holds DNA fragments ending in one kind of base (G, C, A or T), and reading the bands from bottom to top gives the base sequence. Modern sequencing machines do the same job automatically. Comparing the sequence of a gene from one person with a reference sequence shows exactly which base has been <strong>substituted</strong>, <strong>deleted</strong> or added.</p><p class="small">Finding a difference is only the first step. Because the code is <strong>degenerate</strong>, a substitution may not change the amino acid at all, so scientists translate both sequences, codon by codon, to see whether the polypeptide differs, exactly the method you use in exam questions.</p>`,
        question: { id: `q-${R}-fx2`, ref: R, stmts: S(3, 4), type: "mcq", marks: 1, stem: `Sequencing shows that a person's copy of a gene differs from the reference at one base: the mRNA codon CCU has become CCA.\n${CL(["CCU", "CCA", "CCC", "CCG"])}What is the effect on the polypeptide?`, options: ["None: both codons code for proline", "One proline is replaced by another amino acid", "Translation stops at this codon", "The reading frame shifts after this codon"], answer: 0, explanation: "CCU and CCA (and CCC, CCG) all code for proline. The code is degenerate, so this substitution does not change the amino acid sequence." } },
    ],
    examFocus: `<ul>
<li><strong>Definitions.</strong> Gene mutation: a change in the base sequence of DNA. Mutagen: a physical or chemical agent that <em>increases the frequency</em> of mutations (not "causes mutations").</li>
<li><strong>Substitution v deletion.</strong> Substitution: one codon changes, so at most one amino acid changes (or a stop codon forms, or nothing changes). Deletion: the reading frame shifts, so every codon after it changes.</li>
<li><strong>Explain "no change".</strong> Say <em>the code is degenerate</em>, so the new codon codes for the <em>same amino acid</em>; the primary structure, and so the protein, is unchanged.</li>
<li><strong>Predict from the information given.</strong> Convert to mRNA, split into codons from the start codon, translate with the table given, make the change, re-split, compare. Show the codons in your answer.</li>
<li><strong>Strands.</strong> mRNA is complementary to the template strand and has the coding strand's sequence (T → U). Check which strand the question gives.</li>
<li><strong>Explaining effects</strong>: chain the steps: base → codon → amino acid → R group and bonds → tertiary structure → active site or binding site → function.</li>
<li><span class="badge">supporting</span> You may use silent, missense, nonsense and frameshift, but always say what happens to the amino acids as well.</li></ul>`,
    synoptic: [
      { ref: "3.1.7.3", text: "Semi-conservative replication: where spontaneous errors arise; DNA polymerase." },
      { ref: "3.1.8.1", text: "The genetic code: triplet, non-overlapping, degenerate, universal." },
      { ref: "3.1.8.2", text: "Transcription and translation: template strand, mRNA codons, start and stop codons." },
      { ref: "3.1.1.4", text: "Primary, secondary and tertiary structure: why one changed amino acid can change a protein's shape." },
      { ref: "3.1.3.1", text: "Enzyme active sites: a changed shape can stop the substrate binding." },
      { ref: "3.2.11.2", text: "Mutations in proto-oncogenes and tumour suppressor genes; mutagens as carcinogens." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "What is a gene mutation?", options: ["A change in the base sequence of DNA", "A change in the amino acid sequence that alters the DNA", "The removal of introns from pre-mRNA", "A change in the number of chromosomes"], answer: 0, explanation: "A gene mutation is a change in the base sequence of DNA; any change to the amino acids follows from it." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which statement about mutagens is correct?", options: ["They increase the frequency of mutations", "They are needed for any mutation to happen", "They change one particular base in every cell", "They only affect genes that cause cancer"], answer: 0, explanation: "Mutations arise spontaneously during replication; mutagens make them happen more often, at random places." },
      { id: `q-${R}-qc3`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Why does some base substitution not change the amino acid sequence?", options: ["The genetic code is degenerate: the new codon can code for the same amino acid", "The genetic code is universal", "Substitutions only happen in introns", "The ribosome corrects the mistake"], answer: 0, explanation: "Most amino acids have more than one codon, so the new codon may code for the same amino acid." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why does deleting one base near the start of a gene usually change many amino acids?", options: ["It shifts the reading frame, so every codon after it changes", "It always creates a stop codon at that point", "It removes the start codon", "It changes the tRNA anticodons"], answer: 0, explanation: "The bases after the deletion are regrouped into new triplets (a frameshift)." },
      { id: `q-${R}-qc5`, ref: R, stmts: S(4), type: "gap", marks: 1, stem: `Use the information.\n${CL(["UGG", "UGA"])}`, text: "A substitution changes the mRNA codon UGG to UGA. The polypeptide will be {{1}} than normal.", answers: { 1: ["shorter"] }, explanation: "UGA is a stop codon, so translation ends early." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "Gene mutation.", back: "A change in the base sequence of DNA." },
      { id: `f-${R}-2`, front: "When do gene mutations arise spontaneously?", back: "During DNA replication, when a wrong nucleotide is built in (or one is missed out or added) and is not corrected." },
      { id: `f-${R}-3`, front: "How does a mismatch become a permanent mutation?", back: "At the next replication the strand with the wrong base is a template, so a complementary pair forms: a changed base pair in all descendants." },
      { id: `f-${R}-4`, front: "Mutagen.", back: "A physical or chemical agent that increases the frequency of mutations." },
      { id: `f-${R}-5`, front: "Two physical mutagens.", back: "Ionising radiation (X-rays, gamma rays, radioactive substances) and ultraviolet light." },
      { id: `f-${R}-6`, front: "Example of a chemical mutagen.", back: "Some substances in tobacco smoke (also some industrial chemicals)." },
      { id: `f-${R}-7`, front: "Do mutagens cause particular mutations?", back: "No. They act at random, increasing the chance of changes anywhere in the DNA." },
      { id: `f-${R}-8`, front: "Base substitution.", back: "One base is replaced by a different base; only one codon changes." },
      { id: `f-${R}-9`, front: "Base deletion.", back: "One base is removed; the reading frame shifts, so every codon after it changes." },
      { id: `f-${R}-10`, front: "Three possible results of a base substitution.", back: "Same amino acid (no change); a different amino acid; or a stop codon (shorter polypeptide)." },
      { id: `f-${R}-11`, front: "Why can a substitution leave the amino acid sequence unchanged?", back: "The code is degenerate: the new codon can code for the same amino acid." },
      { id: `f-${R}-12`, front: "Which substitutions are most often silent?", back: "Changes to the third base of a codon (codons for one amino acid often differ only in the third base)." },
      { id: `f-${R}-13`, front: "Why does a substitution change at most one amino acid?", back: "The code is non-overlapping: each base is in only one codon." },
      { id: `f-${R}-14`, front: "Why is a deletion usually more harmful than a substitution?", back: "It shifts the reading frame: many amino acids change and a stop codon often appears early." },
      { id: `f-${R}-15`, front: "Silent, missense, nonsense (supporting terms).", back: "Silent: same amino acid. Missense: different amino acid. Nonsense: a stop codon is formed." },
      { id: `f-${R}-16`, front: "Frameshift (supporting term).", back: "A deletion (or insertion) of bases not in a multiple of three, which regroups every later codon." },
      { id: `f-${R}-17`, front: "Template strand to mRNA.", back: "Pair each base: A→U, T→A, G→C, C→G. (Coding strand to mRNA: change T to U.)" },
      { id: `f-${R}-18`, front: "Method for predicting a mutation's effect.", back: "Convert to mRNA; split into codons from the start codon; translate with the table given; make the change; re-split; compare." },
      { id: `f-${R}-19`, front: "How can one changed amino acid stop a protein working?", back: "A different R group changes the hydrogen, ionic and disulfide bonds, so the tertiary structure (for example the active site) changes." },
      { id: `f-${R}-20`, front: "Sickle-cell haemoglobin: the mutation.", back: "A base substitution in HBB: GAG (Glu) → GTG (Val); one amino acid changed." },
      { id: `f-${R}-21`, front: "Do all mutations cause cancer or disease?", back: "No. Many have no effect; cancer needs particular mutations, usually several, in genes controlling division." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "During which process do most spontaneous gene mutations arise?", options: ["DNA replication", "Translation", "Splicing of pre-mRNA", "Protein folding"], answer: 0, explanation: "Errors in copying the base sequence during DNA replication change the DNA itself; errors in translation or splicing do not change the gene." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which of these is a physical mutagen?", options: ["Ultraviolet light", "A chemical in tobacco smoke", "DNA polymerase", "A stop codon"], answer: 0, explanation: "UV light (and ionising radiation) are physical mutagens; substances in tobacco smoke are chemical mutagens." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Workers exposed to a chemical mutagen were found to have more gene mutations than unexposed workers. Which conclusion is correct?", options: ["The chemical increased the rate at which mutations occur", "Unexposed workers had no gene mutations", "The chemical caused the same mutation in every worker", "Every mutation in the exposed workers was caused by the chemical"], answer: 0, explanation: "Mutations happen spontaneously in everyone; a mutagen increases their frequency, at random sites, so some mutations in exposed workers would have happened anyway." },
      { id: `q-${R}-m4`, ref: R, stmts: S(3, 4), type: "mcq", marks: 1, stem: `A DNA template strand contains the triplet CCA. A substitution changes it to CCG.\n${CL(["GGU", "GGC", "GGA", "GGG"])}What is the effect on the polypeptide?`, options: ["None: the mRNA codon changes from GGU to GGC, and both code for glycine", "Glycine is replaced by proline", "The polypeptide ends at this codon", "Every amino acid after this point changes"], answer: 0, explanation: "Template CCA → mRNA GGU; template CCG → mRNA GGC. Both code for Gly: the code is degenerate." },
      { id: `q-${R}-m5`, ref: R, stmts: S(4), type: "mcq", marks: 1, stem: `An mRNA reads AUG UUC AAA UGG CAU UAA. A substitution changes the fourth codon to UGA.\n${CL(["AUG", "UUC", "AAA", "UGG", "CAU", "UGA", "UAA"])}How many amino acids are in the polypeptide made from the mutated mRNA?`, options: ["3", "4", "5", "6"], answer: 0, explanation: "Met, Phe, Lys, then UGA is a stop codon: 3 amino acids instead of 5." },
      { id: `q-${R}-m6`, ref: R, stmts: S(2, 4), type: "mcq", marks: 1, stem: `An mRNA reads AUG GCA UUU UGG CAG UAA (Met–Ala–Phe–Trp–Gln). The first G of the second codon is deleted.\n${CL(["AUG", "GCA", "UUU", "UGG", "CAG", "CAU", "UUU", "GGC", "AGU"])}What are the first four amino acids of the new polypeptide?`, options: ["Met–His–Phe–Gly", "Met–Ala–Phe–Trp", "Met–Phe–Trp–Gln", "Met–His–Phe–Trp"], answer: 0, explanation: "New mRNA: AUG CAU UUU GGC AGU AA. Met–His–Phe–Gly–Ser: every codon after the deletion is regrouped." },
      { id: `q-${R}-m7`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Which statement about the degenerate genetic code is correct?", options: ["Most amino acids are coded for by more than one codon", "Each codon codes for more than one amino acid", "Every base substitution changes an amino acid", "Some bases are read as part of two codons"], answer: 0, explanation: "Degenerate means more than one codon for most amino acids. Each codon still has one meaning, and the code is non-overlapping." },
      { id: `q-${R}-m8`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Methionine has only one codon (AUG). What does this mean for a substitution in an AUG codon inside a gene?", options: ["Any substitution changes the amino acid (or creates a stop codon)", "A change in the third base never changes the amino acid", "It can only be silent", "It always shifts the reading frame"], answer: 0, explanation: "With a single codon there is no other codon for the same amino acid, so degeneracy gives no protection." },
      { id: `q-${R}-m9`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which of these mutations in a gene of 300 codons is most likely to change the most amino acids?", options: ["Deletion of one base in codon 5", "Deletion of one base in codon 295", "Substitution of one base in codon 5", "Substitution of the third base of codon 150"], answer: 0, explanation: "A deletion near the start shifts the reading frame for almost the whole gene; a substitution changes at most one codon." },
      { id: `q-${R}-m10`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: "In the sickle-cell allele of the HBB gene, the codon GAG in the coding strand becomes GTG. Which describes this mutation?", options: ["A base substitution that changes one amino acid", "A base deletion that shifts the reading frame", "A base substitution with no effect, because the code is degenerate", "A base substitution that creates a stop codon"], answer: 0, explanation: "One base is replaced (A by T); GAG codes for glutamate and GUG for valine, so one amino acid changes." },
      // ---- gap fills ----
      { id: `q-${R}-g1`, ref: R, stmts: S(1, 2), type: "gap", marks: 3, stem: "Complete the passage.", text: "A change in the base sequence of DNA is a gene {{1}}. These arise spontaneously during DNA {{2}}. When one base is replaced by a different base, the mutation is a base {{3}}.", answers: { 1: ["mutation"], 2: ["replication"], 3: ["substitution"] }, explanation: "Mutation; replication; substitution." },
      { id: `q-${R}-g2`, ref: R, stmts: S(4), type: "gap", marks: 2, stem: `A DNA template strand reads TAC AAA CTT ACC ATT (3′→5′).\n${CL(["AUG", "UUU", "GAA", "UGG", "UAA", "UGA"])}`, text: "The mRNA is AUG UUU GAA UGG UAA, so the polypeptide has {{1}} amino acids. If the template triplet ACC changes to ACT, the polypeptide has {{2}} amino acids.", answers: { 1: ["4", "four"], 2: ["3", "three"] }, explanation: "Met–Phe–Glu–Trp then stop (4). ACT gives the mRNA codon UGA, a stop codon, so Met–Phe–Glu (3)." },
      // ---- match, sequence ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(1, 2, 3), type: "match", marks: 4, stem: "Match each term to its meaning.", pairs: [{ left: "Mutagen", right: "An agent that increases the frequency of mutations" }, { left: "Base substitution", right: "One base replaced by another; one codon changes" }, { left: "Base deletion", right: "One base removed; the reading frame shifts" }, { left: "Degenerate code", right: "Most amino acids have more than one codon" }] },
      { id: `q-${R}-sq1`, ref: R, stmts: S(4), type: "sequence", marks: 3, stem: "Put these steps in order to predict the effect of a mutation given a DNA template strand and part of the genetic code.", steps: ["Write the mRNA complementary to the template strand", "Split the mRNA into codons from the start codon", "Translate each codon using the table provided", "Make the same change in the template strand and write the new mRNA", "Re-split the new mRNA into codons from the start codon and translate it", "Compare the two amino acid sequences"], explanation: "Convert, split, translate, mutate, re-split and translate, compare." },
      // ---- short answers and data ----
      { id: `q-${R}-s1`, ref: R, stmts: S(1), type: "short", marks: 3, stem: "Explain how a gene mutation can arise spontaneously, and how a mutagen affects the occurrence of mutations. (3 marks)", scheme: [{ point: "During DNA replication a wrong (non-complementary) nucleotide is inserted / a base is missed or added", marks: 1 }, { point: "If not corrected, the change is copied at the next replication, so the base sequence is permanently changed", marks: 1 }, { point: "A mutagen (physical or chemical) increases the frequency / rate of mutations (it does not cause a particular change)", marks: 1 }], model: "During DNA replication, DNA polymerase occasionally joins a nucleotide whose base is not complementary to the template, or a base is missed out. If this is not corrected, at the next replication the wrong base acts as a template, so the change becomes a permanent change in the base sequence. A mutagen, such as UV light, ionising radiation or a chemical in tobacco smoke, increases the frequency of these changes, at random places in the DNA.", commonErrors: "Saying that mutations only happen when a mutagen is present." },
      { id: `q-${R}-s2`, ref: R, stmts: S(3), type: "short", marks: 2, stem: "Explain why a base substitution may have no effect on the polypeptide produced. (2 marks)", scheme: [{ point: "The genetic code is degenerate / most amino acids have more than one codon", marks: 1 }, { point: "So the new codon may code for the same amino acid: same amino acid sequence / primary structure", marks: 1 }], model: "The genetic code is degenerate: most amino acids are coded for by more than one codon. A substitution may change a codon into another codon for the same amino acid, so the amino acid sequence of the polypeptide is unchanged.", commonErrors: "Saying 'the code is universal'; saying the base is 'not important'." },
      { id: `q-${R}-d1`, ref: R, stmts: S(2, 4), type: "short", marks: 4, stem: `Data. Part of the template strand of a gene (3′→5′) reads TAC AAG CCA GTA ACT.\n${CL(DCODONS)}(a) Give the amino acid sequence coded for. (1 mark) (b) The 9th base of the template strand changes from A to G. Give the effect on the amino acid sequence and explain it. (1 mark) (c) Instead, the 4th base of the template strand (A) is deleted. Give the first four amino acids coded for, and explain why they differ from (a). (2 marks)`, scheme: [{ point: "(a) Met–Phe–Gly–His (mRNA AUG UUC GGU CAU UGA)", marks: 1 }, { point: "(b) No change: GGU becomes GGC, which also codes for glycine (degenerate code)", marks: 1 }, { point: "(c) Met–Ser–Val–Ile (mRNA AUG UCG GUC AUU …)", marks: 1 }, { point: "(c) The deletion shifts the reading frame, so every codon after it is regrouped / changed", marks: 1 }], model: `(a) The mRNA is ${sp(DM)}, so Met–Phe–Gly–His (then stop). (b) The third codon of the mRNA changes from GGU to ${P.codons(DS)[2]}; both code for glycine, so the amino acid sequence is unchanged. (c) The mRNA becomes ${sp(DD)}: Met–Ser–Val–Ile. Deleting one base moves every later base back one place, so the codons after the deletion are regrouped (the reading frame shifts).`, commonErrors: "Translating the template strand directly as if it were mRNA; not re-splitting after the deletion." },
      { id: `q-${R}-d2`, ref: R, stmts: S(2, 4), type: "short", marks: 3, stem: `Data. An mRNA reads AUG UCU AAA GGC UGG AUU UAG (Met–Ser–Lys–Gly–Trp–Ile).\n${CL(["AUG", "UCU", "AAA", "GGC", "UGG", "AUU", "UAG", "UAA", "UGA"])}Tryptophan is coded for only by UGG. A biologist says: "Any substitution in the fifth codon will change the polypeptide." Use the information to evaluate this statement. (3 marks)`, scheme: [{ point: "Tryptophan has only one codon (UGG) in the code, so a change to any base gives a different codon meaning", marks: 1 }, { point: "e.g. UGA or UAG would be stop codons: polypeptide ends after Gly (4 amino acids)", marks: 1 }, { point: "Other changes give a different amino acid; so the statement is correct for this codon (degeneracy does not protect it)", marks: 1 }], model: "The fifth codon is UGG, which codes for tryptophan, and tryptophan has only one codon. So any substitution changes it: changing the second or third G to A gives UAG or UGA, stop codons, so the polypeptide would end after Met–Ser–Lys–Gly; other changes give a different amino acid. For this codon the statement is correct, although it would not be true of most codons, because the code is degenerate.", commonErrors: "Arguing that the third base never matters." },
      { id: `q-${R}-s3`, ref: R, stmts: S(2, 3), type: "short", marks: 3, stem: "Explain why a base deletion near the start of a gene is likely to have a greater effect on the protein than a base substitution in the same position. (3 marks)", scheme: [{ point: "A substitution changes only one codon / at most one amino acid (or none, as the code is degenerate)", marks: 1 }, { point: "A deletion shifts the reading frame: every later codon changes, so many amino acids change / an early stop codon", marks: 1 }, { point: "So the primary structure, and therefore the tertiary structure and function, are much more likely to be changed", marks: 1 }], model: "A substitution changes one codon, so at most one amino acid changes, and because the code is degenerate it may not change at all. A deletion moves every later base back by one, so all codons after it are read in a new frame and almost every amino acid changes, often with an early stop codon. The primary structure is greatly altered, so the protein is unlikely to fold correctly or work.", commonErrors: "Saying a deletion removes one amino acid." },
      { id: `q-${R}-s4`, ref: R, stmts: S(3, 4), type: "short", marks: 3, stem: "A substitution changes one amino acid in an enzyme, but the enzyme still works normally. Suggest two reasons for this. (3 marks)", scheme: [{ point: "The new amino acid has a similar R group (similar properties), so the same bonds form", marks: 1 }, { point: "The change is not in / near the active site, so the active site keeps its shape", marks: 1 }, { point: "So the tertiary structure is not changed (enough) to affect substrate binding", marks: 1 }], model: "The new amino acid may have an R group similar to the old one, so the same hydrogen and ionic bonds can form. Or the changed amino acid may be in a part of the enzyme away from the active site. Either way the tertiary structure, and in particular the shape of the active site, is not changed enough to stop the substrate binding.", commonErrors: "Saying the code is degenerate (the amino acid did change here)." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2, 3, 4), type: "extended", marks: 6, stem: "Extended response. Describe how gene mutations arise and explain why different gene mutations can have very different effects on the protein a gene codes for. (6 marks)", scheme: [{ point: "Gene mutation: a change in the base sequence of DNA", marks: 1 }, { point: "Arise spontaneously, during DNA replication (wrong base inserted, missed or added)", marks: 1 }, { point: "Mutagens, physical (UV, ionising radiation) or chemical, increase the frequency", marks: 1 }, { point: "Substitution changes only one codon; may give the same amino acid because the code is degenerate (no effect)", marks: 1 }, { point: "Substitution may give a different amino acid or a stop codon (shorter polypeptide)", marks: 1 }, { point: "Deletion shifts the reading frame, so all later codons / many amino acids change", marks: 1 }, { point: "Changed primary structure changes bonds / folding / tertiary structure, e.g. active site, so function may be lost; effect depends on position", marks: 1 }], alternatives: ["Maximum 6 marks."], levels: [{ level: 3, marks: "5–6", descriptor: "Accurate account of how mutations arise, with the role of mutagens; compares substitution and deletion and links the amino acid change to the protein's structure and function, including the degenerate code." }, { level: 2, marks: "3–4", descriptor: "Describes substitution and deletion and some effects; origin of mutations or link to protein structure is incomplete." }, { level: 1, marks: "1–2", descriptor: "Some correct statements about mutations with little explanation." }], model: "A gene mutation is a change in the base sequence of DNA. Mutations arise spontaneously during DNA replication, when a wrong nucleotide is built in, or one is missed out, and the error is not corrected; at the next replication it becomes a permanent change. Mutagens, such as ultraviolet light, ionising radiation and some chemicals in tobacco smoke, increase the frequency of mutation. In a base substitution one base is replaced, so only one codon changes. Because the code is degenerate the new codon may code for the same amino acid, with no effect at all; or it may code for a different amino acid, or be a stop codon, so the polypeptide is shorter. In a base deletion every base after it moves back, so the reading frame shifts and almost every later amino acid changes. A changed amino acid sequence can change the R groups that form hydrogen, ionic and disulfide bonds, so the polypeptide folds into a different tertiary structure; if the active site or a binding site changes, the protein may not work. A change far from the active site, or to a similar amino acid, may have little effect.", commonErrors: "Saying mutations are caused only by mutagens; saying every mutation changes the protein; missing the reading-frame explanation." },
    ],
  };
})();
